u1=U("forms","Passive forms: is done, was done, has been done","B1",
 "The passive puts the action or result first and the doer second (or nowhere). Form: be + past participle. Change the tense of be, keep the participle.",
 "passive-এ কাজটা গুরুত্বপূর্ণ, কে করেছে তা নয়। গঠন: be + past participle। কাল বদলালে শুধু be বদলায়।",
 [("Present / past","The report is checked daily. · The report was checked yesterday."),("Perfect","The payment has been made. · The payment had been made."),("Modal","It must be signed. · It can be done. · It should have been sent.")],
 [("Use the passive when the doer is unknown or unimportant.","কে করেছে জানা নেই বা দরকার নেই।","My phone was stolen on the bus."),
  ("Present simple passive for processes and routines.","নিয়মিত প্রক্রিয়া।","All invoices are approved by Finance."),
  ("Present perfect passive for news and results.","সদ্য ঘটে যাওয়া ফলাফল।","The new branch has been opened in Uttara."),
  ("Modal + be + participle for rules and requests.","নিয়ম: must/should/can + be + V3।","This form must be submitted by Friday."),
  ("Add by + doer only when it matters.","by + কর্তা, প্রয়োজন হলে।","The design was approved by the client.")],
 ["be + V3","by","has been","must be","was made"],
 [("The meeting was postpone.","The meeting was postponed.","Passive needs the past participle.","be-এর পরে V3।"),
  ("The office cleaned every day.","The office is cleaned every day.","Passive needs be.","be বাদ দেওয়া যাবে না।"),
  ("This happened by mistake was.","This was done by mistake. / This happened by mistake.","Happen has no passive.","happen, arrive, die-এর passive হয় না।")],
 [C("A notice at work.","The lift ___ every Monday morning.",["is serviced","services","is servicing","serviced"],"is serviced","Present simple passive: a routine."),
  C("Bad news.","Rafi's laptop ___ from his desk last week.",["was stolen","stole","is stolen","was steal"],"was stolen","Past passive, doer unknown."),
  T("Project update.","Good news: the contract has ___ (sign).","sign",["been signed"],"Present perfect passive: has been + V3."),
  T("Office rules.","All visitors must ___ (register) at reception.","register",["be registered"],"Modal passive: must be + V3."),
  F("Pick the correct sentence.",["The goods was delivered yesterday.","The goods were delivered yesterday.","The goods delivered yesterday by.","The goods were deliver yesterday."],"The goods were delivered yesterday.","Plural subject: were + V3."),
  B("পদ্মা সেতু ২০২২ সালে খোলা হয়েছিল।",["The Padma Bridge was opened in 2022.","The Padma Bridge opened by 2022.","The Padma Bridge is opened in 2022.","The Padma Bridge was open in 2022."],"The Padma Bridge was opened in 2022.","Past passive with a past date."),
  C("A missed deadline.","The files should ___ yesterday.",["have been sent","be sent","have sent","been sent"],"have been sent","Past modal passive: should have been + V3.",True),
  F("Pick the correct sentence.",["The flight was arrived late.","The flight arrived late.","The flight was arrive late.","The flight is arrived late."],"The flight arrived late.","Arrive has no passive.",True)])
u2=U("reports","Passive in reports and formal writing","B2",
 "Reports, minutes and official emails use the passive to sound objective: 'It was decided...', 'Mistakes were made', 'It is expected that...'. Use it to focus on results and avoid blaming people.",
 "রিপোর্ট ও অফিসিয়াল ইমেইলে passive ব্যবহার করলে লেখা নিরপেক্ষ শোনায় এবং কাউকে দোষ দেওয়া হয় না।",
 [("Impersonal it","It was agreed that... · It is expected that... · It has been reported that..."),("Subject + passive + to","Prices are expected to rise. · He is said to be very strict.")],
 [("Minutes: It was agreed / decided that...","মিটিংয়ের সিদ্ধান্ত লেখা।","It was agreed that the launch would move to June."),
  ("Forecasts: X is expected to...","পূর্বাভাস।","Sales are expected to grow by 10%."),
  ("Polite complaints: focus on the problem, not the person.","দোষারোপ না করে সমস্যা বলা।","The wrong amount was charged to our account."),
  ("Instructions in formal notices.","অফিসিয়াল নির্দেশনা।","Staff are requested to wear ID cards."),
  ("Results in reports: present perfect passive.","ফলাফল জানানো।","Twenty new clients have been added this quarter.")],
 ["it was agreed","is expected to","are requested","has been reported"],
 [("It was decided to the meeting that...","It was decided at the meeting that...","Preposition: at the meeting.","at the meeting।"),
  ("Prices are expected rise.","Prices are expected to rise.","Expected + to.","expected-এর পরে to।"),
  ("Staff are requested wearing ID cards.","Staff are requested to wear ID cards.","Requested + to.","requested + to + verb।")],
 [C("Meeting minutes.","It ___ that the budget would be reviewed in May.",["was agreed","agreed","was agree","has agreeing"],"was agreed","Impersonal passive."),
  C("A market report.","Fuel prices ___ to rise next month.",["are expected","expect","are expecting","expected"],"are expected","Forecast: be expected to."),
  T("A formal notice.","All staff are ___ (request) to attend the safety training.","request",["requested"],"Be requested to."),
  T("A quarterly report.","Three new branches have ___ (open) this year.","open",["been opened"],"Present perfect passive."),
  F("Pick the most professional sentence for a complaint.",["You charged us the wrong amount, you made a big mistake.","We were charged the wrong amount on the last invoice.","We charged the wrong amount on the last invoice.","The wrong amount charged us on the last invoice."],"We were charged the wrong amount on the last invoice.","Passive focuses on the problem politely."),
  B("জানা গেছে যে নতুন অফিসটা আগামী মাসে খুলবে।",["It has been reported that the new office will open next month.","It has reported that the new office will open next month.","It is report that the new office will open next month.","It reported that the new office will be open next month by."],"It has been reported that the new office will open next month.","Impersonal passive: it has been reported that."),
  C("A reference about a manager.","Mr Karim ___ to be very fair with his team.",["is said","says","is saying","said"],"is said","Be said to: people say that he is.",True),
  F("Pick the correct sentence.",["The project is expected to finish by December.","The project is expected finishing by December.","The project expects to be finish by December.","The project is expect to finish by December."],"The project is expected to finish by December.","Be expected + to + base.",True)])
u3=U("causative","Have / get something done","B2",
 "Use have or get + object + past participle when someone else does a job for you, usually a service you pay for. Get is a little more informal.",
 "অন্য কাউকে দিয়ে কাজ করানো (যেমন চুল কাটানো, গাড়ি সারানো): have/get + object + V3।",
 [("Have","have + thing + V3: I had my car serviced."),("Get","get + thing + V3: I need to get my passport renewed."),("Bad experience","have + thing + V3: He had his wallet stolen.")],
 [("Services you arrange.","টাকা দিয়ে অন্যকে দিয়ে করানো।","I'm having my flat painted next week."),
  ("Get is common in speech.","কথ্য ভাষায় get।","Where do you get your hair cut?"),
  ("Order: have + object + participle.","শব্দক্রম: have + জিনিস + V3।","We had the AC repaired. (not: we had repaired the AC)"),
  ("Bad things that happened to you.","খারাপ অভিজ্ঞতা।","Rafi had his phone snatched near Farmgate."),
  ("Any tense: change have/get.","কাল বদলাতে have/get বদলান।","I'll get the documents printed tomorrow.")],
 ["have it done","get it done","repaired","serviced","cut"],
 [("I cut my hair yesterday.","I had my hair cut yesterday.","If a barber did it, use have + object + V3.","নিজে না করলে have something done।"),
  ("I had repaired my laptop.","I had my laptop repaired.","Object comes before the participle.","জিনিসটা আগে, V3 পরে।"),
  ("I need to get my passport renew.","I need to get my passport renewed.","Use the past participle.","V3 লাগবে।")],
 [C("Car trouble.","I need to ___ before the trip to Sylhet.",["have my car serviced","service my car by someone","have serviced my car","get my car service"],"have my car serviced","Have + object + V3."),
  C("A new look.","She ___ at a salon in Dhanmondi.",["had her hair cut","cut her hair","had cut her hair","had her hair cutting"],"had her hair cut","Someone else cut it."),
  T("Travel papers.","I'm going to get my visa ___ (extend) next week.","extend",["extended"],"Get + object + V3."),
  T("Moving flat.","We're having the walls ___ (paint) before we move in.","paint",["painted"],"Have + object + V3."),
  F("Pick the correct sentence.",["I had my phone screen replaced.","I had replaced my phone screen by a shop.","I had my phone screen replace.","I replaced my phone screen at the shop by them."],"I had my phone screen replaced.","Have + object + V3."),
  B("আমি কাল আমার ল্যাপটপ সারিয়েছি (দোকানে)।",["I had my laptop repaired yesterday.","I repaired my laptop yesterday.","I had repaired my laptop yesterday.","I had my laptop repair yesterday."],"I had my laptop repaired yesterday.","A shop did it: had + object + V3."),
  C("A bad day.","Rafi ___ on the bus to Motijheel.",["had his wallet stolen","stole his wallet","had stolen his wallet","was stolen his wallet"],"had his wallet stolen","Bad experience: have + object + V3.",True),
  C("Office printing.","Can you ___ before the meeting?",["get these copies printed","get printed these copies","get these copies print","print these copies get"],"get these copies printed","Get + object + V3.",True)])
