  C("A haircut.","I usually ___ once a month.",["get my hair cut","cut my hair by a barber","get cut my hair","get my hair cutting"],"get my hair cut","Get + object + V3."),
  C("A forecast.","Inflation ___ to fall next year.",["is expected","expects","is expecting","expected"],"is expected","Be expected to.",True),
